export const conciergeEntryById = new Map(
  conciergeEntries.map((entry) => [entry.id, entry]),
);

export function getConciergeEntry(id: string) {
  const entry = conciergeEntryById.get(id);
  return entry?.enabled ? entry : undefined;
}
